45	 */
46	@Controller
47	@RequestMapping("/owners/{ownerId}")
48	class PetController {
49	
50		private static final String VIEWS_PETS_CREATE_OR_UPDATE_FORM = "pets/createOrUpdatePetForm";
51	
52		private final OwnerRepository owners;
53	
54		private final PetTypeRepository types;
55	
56		public PetController(OwnerRepository owners, PetTypeRepository types) {
57			this.owners = owners;
58			this.types = types;
59		}
60	
61		@ModelAttribute("types")
62		public Collection<PetType> populatePetTypes() {
63			return this.types.findPetTypes();
64		}
65	
66		@ModelAttribute("owner")
67		public Owner findOwner(@PathVariable("ownerId") int ownerId) {
68			Optional<Owner> optionalOwner = this.owners.findById(ownerId);
69			Owner owner = optionalOwner.orElseThrow(() -> new IllegalArgumentException(
70					"Owner not found with id: " + ownerId + ". Please ensure the ID is correct "));
71			return owner;
72		}
73	
74		@ModelAttribute("pet")
75		public Pet findPet(@PathVariable("ownerId") int ownerId,
76				@PathVariable(name = "petId", required = false) Integer petId) {
77	
78			if (petId == null) {
79				return new Pet();
80			}
81	
82			Optional<Owner> optionalOwner = this.owners.findById(ownerId);
83			Owner owner = optionalOwner.orElseThrow(() -> new IllegalArgumentException(
84					"Owner not found with id: " + ownerId + ". Please ensure the ID is correct "));
85			return owner.getPet(petId);
86		}
87	
88		@InitBinder("owner")
89		public void initOwnerBinder(WebDataBinder dataBinder) {
90			dataBinder.setDisallowedFields("id");
91		}
92	
93		@InitBinder("pet")
94		public void initPetBinder(WebDataBinder dataBinder) {
95			dataBinder.setValidator(new PetValidator());
96		}
97	
98		@GetMapping("/pets/new")
99		public String initCreationForm(Owner owner, ModelMap model) {
100			Pet pet = new Pet();
101			owner.addPet(pet);
102			return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
103		}
104	
105		@PostMapping("/pets/new")
106		public String processCreationForm(Owner owner, @Valid Pet pet, BindingResult result,
107				RedirectAttributes redirectAttributes) {
108	
109			if (StringUtils.hasText(pet.getName()) && pet.isNew() && owner.getPet(pet.getName(), true) != null) {
110				result.rejectValue("name", "duplicate", "already exists");
111			}
112	
113			LocalDate currentDate = LocalDate.now();
114			if (pet.getBirthDate() != null && pet.getBirthDate().isAfter(currentDate)) {
115				result.rejectValue("birthDate", "typeMismatch.birthDate");
116			}
117	
118			if (result.hasErrors()) {
119				return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
120			}
121	
122			owner.addPet(pet);
123			this.owners.save(owner);
124			redirectAttributes.addFlashAttribute("message", "New Pet has been Added");
125			return "redirect:/owners/{ownerId}";
126		}
127	
128		@GetMapping("/pets/{petId}/edit")
129		public String initUpdateForm() {
130			return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
131		}
132	
133		@PostMapping("/pets/{petId}/edit")
134		public String processUpdateForm(Owner owner, @Valid Pet pet, BindingResult result,
135				RedirectAttributes redirectAttributes) {
136	
137			String petName = pet.getName();
138	
139			// checking if the pet name already exists for the owner
140			if (StringUtils.hasText(petName)) {
141				Pet existingPet = owner.getPet(petName, false);
142				if (existingPet != null && !Objects.equals(existingPet.getId(), pet.getId())) {
143					result.rejectValue("name", "duplicate", "already exists");
144				}
145			}
146	
147			LocalDate currentDate = LocalDate.now();
148			if (pet.getBirthDate() != null && pet.getBirthDate().isAfter(currentDate)) {
149				result.rejectValue("birthDate", "typeMismatch.birthDate");
150			}
151	
152			if (result.hasErrors()) {
153				return VIEWS_PETS_CREATE_OR_UPDATE_FORM;
154			}
155	
156			updatePetDetails(owner, pet);
157			redirectAttributes.addFlashAttribute("message", "Pet details has been edited");
158			return "redirect:/owners/{ownerId}";
159		}
160	
161		/**
162		 * Updates the pet details if it exists or adds a new pet to the owner.
163		 * @param owner The owner of the pet
164		 * @param pet The pet with updated details
165		 */
166		private void updatePetDetails(Owner owner, Pet pet) {
167			Integer id = pet.getId();
168			Assert.state(id != null, "'pet.getId()' must not be null");
169			Pet existingPet = owner.getPet(id);
170			if (existingPet != null) {
171				// Update existing pet's properties
172				existingPet.setName(pet.getName());
173				existingPet.setBirthDate(pet.getBirthDate());
174				existingPet.setType(pet.getType());
175			}
176			else {
177				owner.addPet(pet);
178			}
179			this.owners.save(owner);
180		}
181	
182	}
