	/**
	 * Custom handler for displaying an owner.
	 * @param ownerId the ID of the owner to display
	 * @return a ModelMap with the model attributes for the view
	 */
	@GetMapping("/owners/{ownerId}")
	public ModelAndView showOwner(@PathVariable("ownerId") int ownerId) {
		ModelAndView mav = new ModelAndView("owners/ownerDetails");
		Optional<Owner> optionalOwner = this.owners.findById(ownerId);
		Owner owner = optionalOwner.orElseThrow(() -> new IllegalArgumentException(
				"Owner not found with id: " + ownerId + ". Please ensure the ID is correct "));
		mav.addObject(owner);
		return mav;
	}

	/**
	 * Record new weight for a pet.
	 * @param ownerId the ID of the owner
	 * @param petId the ID of the pet
	 * @param weightRecord the weight record to create
	 * @return ResponseEntity with created weight record or error status
	 */
	@PostMapping("/owners/{ownerId}/pets/{petId}/weight")
	@ResponseBody
	public ResponseEntity<WeightRecord> recordWeight(@PathVariable("ownerId") int ownerId,
			@PathVariable("petId") int petId, @Valid @RequestBody WeightRecord weightRecord,
			BindingResult result) {

		if (result.hasErrors()) {
			return ResponseEntity.badRequest().build();
		}

		if (weightRecord.getWeightKg() == null) {
			return ResponseEntity.badRequest().build();
		}

		Optional<Owner> optionalOwner = this.owners.findById(ownerId);
		if (optionalOwner.isEmpty()) {
			return ResponseEntity.notFound().build();
		}

		Owner owner = optionalOwner.get();
		Pet pet = owner.getPet(petId);
		if (pet == null) {
			return ResponseEntity.notFound().build();
		}

		weightRecord.setPetId(petId);
		WeightRecord savedRecord = this.weightRecords.save(weightRecord);
		return ResponseEntity.status(HttpStatus.CREATED).body(savedRecord);
	}

	/**
	 * Get weight history for a pet.
	 * @param ownerId the ID of the owner
	 * @param petId the ID of the pet
	 * @return ResponseEntity with list of weight records or error status
	 */
	@GetMapping("/owners/{ownerId}/pets/{petId}/weight/history")
	@ResponseBody
	public ResponseEntity<List<WeightRecord>> getWeightHistory(@PathVariable("ownerId") int ownerId,
			@PathVariable("petId") int petId) {

		Optional<Owner> optionalOwner = this.owners.findById(ownerId);
		if (optionalOwner.isEmpty()) {
			return ResponseEntity.notFound().build();
		}

		Owner owner = optionalOwner.get();
		Pet pet = owner.getPet(petId);
		if (pet == null) {
			return ResponseEntity.notFound().build();
		}

		List<WeightRecord> history = this.weightRecords.findByPetIdOrderByRecordDateDesc(petId);
		return ResponseEntity.ok(history);
	}

}

