59		private final WeightRecordRepository weightRecords;
60	
61		public OwnerController(OwnerRepository owners, WeightRecordRepository weightRecords) {
62			this.owners = owners;
63			this.weightRecords = weightRecords;
64		}
65	
66		@InitBinder
67		public void setAllowedFields(WebDataBinder dataBinder) {
68			dataBinder.setDisallowedFields("id");
69		}
70	
71		@ModelAttribute("owner")
72		public Owner findOwner(@PathVariable(name = "ownerId", required = false) Integer ownerId) {
73			return ownerId == null ? new Owner()
74					: this.owners.findById(ownerId)
75						.orElseThrow(() -> new IllegalArgumentException("Owner not found with id: " + ownerId
76								+ ". Please ensure the ID is correct " + "and the owner exists in the database."));
77		}
