79		@GetMapping("/owners/new")
80		public String initCreationForm() {
81			return VIEWS_OWNER_CREATE_OR_UPDATE_FORM;
82		}
83	
84		@PostMapping("/owners/new")
85		public String processCreationForm(@Valid Owner owner, BindingResult result, RedirectAttributes redirectAttributes) {
86			if (result.hasErrors()) {
87				redirectAttributes.addFlashAttribute("error", "There was an error in creating the owner.");
88				return VIEWS_OWNER_CREATE_OR_UPDATE_FORM;
89			}
90	
91			this.owners.save(owner);
92			redirectAttributes.addFlashAttribute("message", "New Owner Created");
93			return "redirect:/owners/" + owner.getId();
94		}
95	
96		@GetMapping("/owners/find")
97		public String initFindForm() {
98			return "owners/findOwners";
99		}
100	
101		@GetMapping("/owners")
102		public String processFindForm(@RequestParam(defaultValue = "1") int page, Owner owner, BindingResult result,
103				Model model) {
104			// allow parameterless GET request for /owners to return all records
105			String lastName = owner.getLastName();
106			if (lastName == null) {
107				lastName = ""; // empty string signifies broadest possible search
108			}
109	
110			// find owners by last name
111			Page<Owner> ownersResults = findPaginatedForOwnersLastName(page, lastName);
112			if (ownersResults.isEmpty()) {
113				// no owners found
114				result.rejectValue("lastName", "notFound", "not found");
115				return "owners/findOwners";
116			}
117	
118			if (ownersResults.getTotalElements() == 1) {
119				// 1 owner found
120				owner = ownersResults.iterator().next();
121				return "redirect:/owners/" + owner.getId();
122			}
123	
124			// multiple owners found
125			return addPaginationModel(page, model, ownersResults);
126		}
127	
128		private String addPaginationModel(int page, Model model, Page<Owner> paginated) {
129			List<Owner> listOwners = paginated.getContent();
130			model.addAttribute("currentPage", page);
131			model.addAttribute("totalPages", paginated.getTotalPages());
132			model.addAttribute("totalItems", paginated.getTotalElements());
133			model.addAttribute("listOwners", listOwners);
134			return "owners/ownersList";
135		}
136	
137		private Page<Owner> findPaginatedForOwnersLastName(int page, String lastname) {
138			int pageSize = 5;
139			Pageable pageable = PageRequest.of(page - 1, pageSize);
140			return owners.findByLastNameStartingWith(lastname, pageable);
141		}
