146		}
147	
148		@PostMapping("/owners/{ownerId}/edit")
149		public String processUpdateOwnerForm(@Valid Owner owner, BindingResult result, @PathVariable("ownerId") int ownerId,
150				RedirectAttributes redirectAttributes) {
151			if (result.hasErrors()) {
152				redirectAttributes.addFlashAttribute("error", "There was an error in updating the owner.");
153				return VIEWS_OWNER_CREATE_OR_UPDATE_FORM;
154			}
155	
156			if (!Objects.equals(owner.getId(), ownerId)) {
157				result.rejectValue("id", "mismatch", "The owner ID in the form does not match the URL.");
158				redirectAttributes.addFlashAttribute("error", "Owner ID mismatch. Please try again.");
159				return "redirect:/owners/{ownerId}/edit";
160			}
161	
162			owner.setId(ownerId);
163			this.owners.save(owner);
164			redirectAttributes.addFlashAttribute("message", "Owner Values Updated");
165			return "redirect:/owners/{ownerId}";
166		}
